  let q = abs(p) - vec2f(0.72, 0.8);
  var sd = length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - 0.14;
  // or straight sides under a round top
  var arch_sd = max(abs(p.x) - 0.8, -0.92 - p.y);
