  let tw = 3.2 * (1.0 - smoothstep(0.0, 1.1, r)) + time * 0.9;
  let w = mat2x2f(cos(tw), -sin(tw), sin(tw), cos(tw)) * p;
  let arms = portal_fbm(w * 2.2 + vec2f(0.0, time * 0.25));
  let fine = portal_fbm(w * 5.5 - vec2f(time * 0.4));
